import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import signalrService from '../services/signalrService';
import UserSearch from '../components/Chat/UserSearch';
import MessageBubble from '../components/Chat/MessageBubble';
import MessageInput from '../components/Chat/MessageInput';
import './ChatPage.css';

const ChatPage = () => {
  const { user } = useAuth();
  const navigate = useNavigate();
  
  const [conversations, setConversations] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [onlineUsers, setOnlineUsers] = useState(new Set());
  const [showUserSearch, setShowUserSearch] = useState(false);
  
  const messagesEndRef = useRef(null);
  const selectedUserRef = useRef(null); // 🔥 Фикс замыкания

  // Синхронизация рефа при изменении выбранного диалога
  useEffect(() => {
    selectedUserRef.current = selectedUser;
  }, [selectedUser]);

  useEffect(() => {
    if (!user) {
      navigate('/login');
      return;
    }
    loadConversations();
    connectSignalR();

    return () => {
      signalrService.stopConnection();
    };
  }, [user, navigate]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const loadConversations = async () => {
    try {
      const response = await api.get('/chat/conversations');
      setConversations(response.data);
      // Не перезаписываем onlineUsers из БД, чтобы не сбрасывать реальные статусы из SignalR
    } catch (error) {
      console.error('Ошибка загрузки диалогов:', error);
    } finally {
      setLoading(false);
    }
  };

  const loadMessages = async (userId) => {
    try {
      const response = await api.get(`/chat/messages/${userId}`);
      setMessages(response.data);
      await api.post(`/chat/mark-read/${userId}`);
    } catch (error) {
      console.error('Ошибка загрузки сообщений:', error);
    }
  };

  const connectSignalR = useCallback(async () => {
    const token = localStorage.getItem('token');
    if (!token) return;

    const connected = await signalrService.startConnection(token);
    if (connected) {
      signalrService.onMessage((message) => {
        const currentSelectedUser = selectedUserRef.current;
        const belongsToChat = currentSelectedUser && (
          (message.senderId === currentSelectedUser.userId && message.recipientId === user?.id) ||
          (message.senderId === user?.id && message.recipientId === currentSelectedUser.userId)
        );

        setMessages(prev => {
          // 1. Если сообщение уже есть, игнорируем
          if (prev.some(m => m.id === message.id)) return prev;

          // 2. Если пришло реальное сообщение, заменяем временное (temp-)
          const isReal = message.id && !String(message.id).startsWith('temp-');
          if (isReal) {
            const tempIndex = prev.findIndex(m =>
              m.id?.startsWith('temp-') &&
              m.content === message.content &&
              m.senderId === message.senderId &&
              Math.abs(new Date(m.sentAt) - new Date(message.sentAt)) < 3000
            );
            if (tempIndex !== -1) {
              const updated = [...prev];
              updated[tempIndex] = { ...message, isOwn: message.senderId === user?.id, isRead: true };
              return updated;
            }
          }

          // 3. Добавляем новое сообщение
          return [...prev, { ...message, isOwn: message.senderId === user?.id, isRead: message.senderId !== user?.id }];
        });

        // Маркируем как прочитанные только если чат открыт и сообщение от собеседника
        if (belongsToChat && message.senderId !== user?.id) {
          api.post(`/chat/mark-read/${currentSelectedUser.userId}`).catch(console.error);
        }
        
        // Обновляем список диалогов раз в секунду при активных сообщениях, чтобы не спамить API
        loadConversations();
      });

      signalrService.onConversationUpdate(() => {
        loadConversations();
      });

      signalrService.onUserStatus((userId, isOnline) => {
        setOnlineUsers(prev => {
          const next = new Set(prev);
          const id = parseInt(userId);
          isOnline ? next.add(id) : next.delete(id);
          return next;
        });
      });
    }
  }, [user]);

  const selectConversation = async (conversation) => {
    setSelectedUser(conversation);
    setShowUserSearch(false);
    await loadMessages(conversation.userId);
  };

  const startNewConversation = async (foundUser) => {
    setSelectedUser({
      userId: foundUser.id,
      username: foundUser.username,
      avatar: foundUser.avatar,
      isOnline: foundUser.isOnline
    });
    setShowUserSearch(false);
    await loadMessages(foundUser.id);
  };

  const handleSendMessage = async () => {
    if (!newMessage.trim() || !selectedUser) return;
    const messageContent = newMessage.trim();
    setNewMessage('');

    try {
      await signalrService.sendMessage(selectedUser.userId, messageContent);
    } catch (error) {
      console.error('Ошибка отправки:', error);
      setNewMessage(messageContent); // Возвращаем текст при ошибке
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
  };

  const formatTime = (dateString) => {
    if (!dateString) return '';
    const date = new Date(dateString);
    return date.toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' });
  };

  if (!user) return null;

  return (
    <div className="chat-page">
      <div className="conversations-panel">
        <div className="conversations-header">
          <h2>💬 Сообщения</h2>
          <span className="online-indicator">🟢 {onlineUsers.size} онлайн</span>
        </div>

        <div className="new-chat-button-container">
          {!showUserSearch ? (
            <button className="btn-new-chat" onClick={() => setShowUserSearch(true)}>✏️ Новый чат</button>
          ) : (
            <button className="btn-cancel-search" onClick={() => setShowUserSearch(false)}>✕ Отмена</button>
          )}
        </div>

        {showUserSearch && (
          <div className="user-search-container">
            <UserSearch onSelectUser={startNewConversation} currentUserId={user?.id} />
          </div>
        )}

        {!showUserSearch && (
          <>
            {loading ? (
              <div className="loader">Загрузка...</div>
            ) : conversations.length > 0 ? (
              <div className="conversations-list">
                {conversations.map(conv => (
                  <div
                    key={conv.userId}
                    className={`conversation-item ${selectedUser?.userId === conv.userId ? 'active' : ''}`}
                    onClick={() => selectConversation(conv)}
                  >
                    <div className={`avatar ${onlineUsers.has(conv.userId) ? 'online' : 'offline'}`}>
                      {conv.avatar ? <img src={conv.avatar} alt={conv.username} /> : conv.username.charAt(0).toUpperCase()}
                    </div>
                    <div className="conversation-info">
                      <div className="conversation-header">
                        <span className="username">{conv.username}</span>
                        {conv.unreadCount > 0 && <span className="unread-badge">{conv.unreadCount}</span>}
                      </div>
                      <div className="last-message">
                        {conv.lastMessage?.substring(0, 30)}{conv.lastMessage?.length > 30 ? '...' : ''}
                      </div>
                      <div className="message-time">{conv.lastMessageAt ? formatTime(conv.lastMessageAt) : ''}</div>
                    </div>
                  </div>
                ))}
              </div>
            ) : (
              <div className="no-conversations">
                <p>😕 Нет диалогов</p>
                <p className="hint">Нажмите "Новый чат" для поиска</p>
              </div>
            )}
          </>
        )}
      </div>

      <div className="messages-panel">
        {selectedUser ? (
          <>
            <div className="chat-header">
              <div className={`avatar ${onlineUsers.has(selectedUser.userId) ? 'online' : 'offline'}`}>
                {selectedUser.avatar ? <img src={selectedUser.avatar} alt={selectedUser.username} /> : selectedUser.username.charAt(0).toUpperCase()}
              </div>
              <div className="chat-info">
                <h3>{selectedUser.username}</h3>
                <span className={`status ${onlineUsers.has(selectedUser.userId) ? 'online' : 'offline'}`}>
                  {onlineUsers.has(selectedUser.userId) ? 'В сети' : 'Был(а) недавно'}
                </span>
              </div>
            </div>

            <div className="messages-container" ref={messagesEndRef}>
              {messages.map((msg, index) => (
                <MessageBubble
                  key={msg.id || index}
                  message={msg.content}
                  isOwn={msg.isOwn}
                  timestamp={formatTime(msg.sentAt)}
                  isRead={msg.isRead}
                />
              ))}
            </div>

            <MessageInput
              value={newMessage}
              onChange={(e) => setNewMessage(e.target.value)}
              onSend={handleSendMessage}
              onKeyPress={handleKeyPress}
              disabled={!signalrService.isConnected()}
            />
          </>
        ) : (
          <div className="no-chat-selected">
            <div className="chat-icon">💬</div>
            <p>Выберите диалог или начните новый чат</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ChatPage;
